import assert from 'node:assert/strict';
import { once } from 'node:events';
import { mkdir, mkdtemp, rm } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { chromium } from 'playwright-core';
import { observeBodyReady } from './helpers/body-startup.mjs';
import { previewServer } from '../scripts/preview.mjs';

const directory = await mkdtemp(join(tmpdir(), 'dsh-inbox-ui-'));
const server = previewServer({ dataDir: directory }); server.listen(0, '127.0.0.1'); await once(server, 'listening');
let browser;
try {
  browser = await chromium.launch({ executablePath: process.env.CHROMIUM_PATH ?? (existsSync('/usr/bin/chromium') ? '/usr/bin/chromium' : chromium.executablePath()), headless: true, args: ['--no-sandbox', '--enable-unsafe-swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 1200, height: 800 }, reducedMotion: 'reduce' });
  page.setDefaultTimeout(12000);
  const errors = []; page.on('pageerror', error => errors.push(error.message));
  await page.addInitScript(() => {
    window.inboxActions = [];
    window.dshPetBridge = { subscribe(fn) { window.inboxReceive = fn; }, action(value) { window.inboxActions.push(value); if(value.type==='select')queueMicrotask(()=>window.inboxReceive({type:'snapshot',snapshot:{...window.inboxFrame,sessionId:value.sessionId}})); }, hit() {} };
  });
  const receive = message => page.evaluate(message => { if(Array.isArray(message.snapshot?.sessions))window.inboxFrame=message.snapshot;window.inboxReceive(message); }, message);
  const actions = () => page.evaluate(() => window.inboxActions.filter(action => ['select', 'read', 'open-session', 'notification-snooze', 'question-answer'].includes(action.type)));
  const resetActions = () => page.evaluate(() => { window.inboxActions = []; });
  const focus = { id: 'focus-full-id', label: '正在聊的会话', project: 'shared', mood: 'idle', unread: 0, chatAvailable: true };
  const a = { id: 'source-abcdef-111', label: '修复状态', project: 'shared', mood: 'idle', unread: 1, chatAvailable: true };
  const b = { ...a, id: 'source-abcdef-222', label: '检查菜单' };
  const reply = (id, session, time, text) => ({ id, sessionId: session.id, time, text, read: false });
  const first = reply('single-full-reply', a, 1, '完整回复。\n' + '最终结果🐳。'.repeat(80));
  const frame = (sessions, results) => ({ mood: 'idle', active: false, sessionId: focus.id, sessions: [focus, ...sessions], results });
  const state = { protocol: 1, runtime: { phase: 'running', visible: true, generation: 8, visibilityRevision: 4, suspended: false }, interactions: [] };
  await page.goto(`http://127.0.0.1:${server.address().port}`);
  await observeBodyReady(page, 'inbox-ui')('#pet[data-character=whale][data-mode]');
  await receive({ type: 'init', options: { locale: 'zh-CN', roam: false }, snapshot: frame([a], [first]) });
  await receive({ type: 'notification-state', snapshot: state });
  await resetActions();
  await page.locator('#attention').click();
  await page.locator('#reader:not([hidden])').waitFor();
  assert.equal(await page.locator('#reader-text').innerText(), first.text, 'one reply opens in full with one click');
  assert.equal(await page.locator('#conversations').isVisible(), false);
  assert.equal(await page.locator('#chat-session-name').innerText(), focus.label);
  assert.deepEqual(await actions(), [{ type: 'read', resultId: first.id }], 'reading acknowledges the exact reply and keeps chat focus');
  await page.keyboard.press('Escape');

  const second = reply('multi-a-full', a, 2, '<img src=x onerror="throw 1"> 已修复状态。\n全文内容。');
  const third = reply('multi-b-full', b, 3, '菜单已经完成。');
  let request = { id: JSON.stringify([a.id, 'question', 'question-call-full']), nativeId: 'question-call-full', sessionId: a.id, kind: 'question', turn: 1, seq: 2, createdAt: 1, preview: '这一步选择哪个方案？', state: 'continued', dueAt: null, automaticReminders: 0 };
  const issue = { id: 'error-source-full', label: '构建检查', mood: 'error', text: '构建失败，请检查。', unread: 0 };
  const waitingA = { ...a, mood: 'waiting' };
  await receive({ type: 'snapshot', snapshot: frame([waitingA, b, issue], [{ ...first, read: true }, second, third]) });
  await receive({ type: 'notification-state', snapshot: { ...state, interactions: [request] } });
  await resetActions();
  await page.locator('#attention').click();
  await page.locator('#requests:not([hidden])').waitFor();
  assert.equal(await page.locator('#inbox-replies .inbox-reply').count(), 2);
  assert.equal(await page.locator('.request-card').count(), 1);
  assert.equal(await page.locator('#inbox-issues .inbox-issue').count(), 1);
  assert.equal(await page.locator('#attention-count').innerText(), '4', 'a question is not counted again as a generic waiting session');
  assert.equal(await page.locator('#inbox-replies img').count(), 0, 'reply summaries are plain text');
  assert.deepEqual(await actions(), [], 'opening a list neither reads replies nor selects a conversation');
  await page.locator(`[data-result-id="${second.id}"][data-action=open]`).click();
  assert.deepEqual(await actions(), [{ type: 'read', resultId: second.id }, { type: 'select', sessionId: a.id }], 'a reply row continues its exact source in the composer');

  await page.locator('#chat-close').click();
  const fourth = reply('multi-c-full', a, 4, '另一份完整回复。');
  await receive({ type: 'snapshot', snapshot: frame([waitingA, b, issue], [{ ...second, read: true }, third, fourth]) });
  await resetActions();
  await page.locator('#attention').click();
  await page.locator(`[data-result-id="${fourth.id}"][data-action=read]`).focus();
  assert.deepEqual(await actions(), [], 'keyboard focus on a summary does not mark it read');
  await page.keyboard.press('Enter');
  assert.equal(await page.locator('#reader-text').innerText(), fourth.text);
  assert.equal(await page.locator('#reader-count').innerText(), '1 / 2');
  const incoming = reply('arrives-while-reading', b, 5, '读到一半新收到的回复。');
  await receive({ type: 'snapshot', snapshot: frame([waitingA, b, issue], [third, fourth, incoming]) });
  assert.equal(await page.locator('#reader-text').innerText(), fourth.text, 'incoming messages cannot replace the open reply');
  assert.equal(await page.locator('#reader-count').innerText(), '1 / 2', 'the active reading order remains stable');
  await page.locator('#reader-next').click();
  assert.equal(await page.locator('#reader-text').innerText(), third.text, 'read consecutively across source sessions');
  assert.equal(await page.locator('#chat-session-name').innerText(), focus.label);
  assert.ok(!(await actions()).some(action => action.type === 'select'));
  await page.locator('#reader-inbox').click();
  assert.equal(await page.locator('#inbox-replies .inbox-reply').count(), 1, 'returning reveals the new unread reply');
  await resetActions();
  await page.locator('[data-request-id][data-action=open]').click();
  assert.deepEqual(await actions(), [{ type: 'open-session', sessionId: a.id }], 'opening a question never reads replies or settles the request');
  await page.locator('#attention').click();
  assert.equal(await page.locator('.request-card').count(), 0, 'viewed continued question leaves the inbox without being answered');
  request = { ...request, id: JSON.stringify([a.id, 'question', 'new-question-call']), nativeId: 'new-question-call' };
  await receive({ type: 'notification-state', snapshot: { ...state, interactions: [request] } });
  assert.equal(await page.locator('.request-card').count(), 1, 'a new call in the same session remains visible');
  await page.locator('[data-request-id][data-action=snooze]').focus();
  await receive({ type: 'notification-state', snapshot: { ...state, interactions: [{ ...request, dueAt: Date.now() + 600000 }] } });
  assert.equal(await page.evaluate(() => document.activeElement.dataset.requestId), request.id, 'request updates preserve keyboard focus on the same action');
  await page.locator('[data-request-id][data-action=snooze]').click();
  assert.deepEqual((await actions()).at(-1), { type: 'notification-snooze', interactionId: request.id, generation: 8 });
  await receive({ type: 'notification-snooze-result', interactionId: request.id, ok: true });
  await receive({ type: 'configure', options: { locale: 'en-US' } });
  assert.equal(await page.locator('#requests-title').innerText(), 'I brought your messages!');
  assert.equal(await page.locator('#inbox-replies [data-action=open]').innerText(), 'Keep chatting');
  await page.setViewportSize({ width: 320, height: 640 });
  await page.waitForFunction(() => { const r = document.getElementById('requests').getBoundingClientRect(); return r.left >= 0 && r.right <= innerWidth && r.top >= 0 && r.bottom <= innerHeight; });
  assert.equal(await page.locator('#requests').evaluate(el => el.scrollWidth <= el.clientWidth), true, 'the inbox fits a small viewport');
  await page.locator('#inbox-list').evaluate(el => { el.scrollTop = 0; });
  await mkdir('artifacts', { recursive: true }); await page.screenshot({ path: 'artifacts/inbox-narrow.png' });
  await page.setViewportSize({ width: 1200, height: 800 });
  await receive({ type: 'configure', options: { locale: 'zh-CN' } });
  await page.waitForFunction(() => {
    const panel = document.getElementById('requests'), pet = document.getElementById('pet').getBoundingClientRect();
    const tail = panel.getBoundingClientRect().left + parseFloat(panel.style.getPropertyValue('--tail'));
    return Math.abs(tail - (pet.left + pet.width / 2)) < 80;
  });
  await page.locator('#inbox-list').evaluate(el => { el.scrollTop = 0; });
  await receive({ type: 'snapshot', snapshot: frame([waitingA, b, { ...issue, mood: 'idle' }], [third, fourth, incoming]) });
  assert.equal(await page.locator('#inbox-issues .inbox-issue').count(), 0, 'a recovered error leaves the inbox');
  const clip = await page.evaluate(() => {
    const panel = document.getElementById('requests').getBoundingClientRect(), pet = document.getElementById('pet').getBoundingClientRect();
    const x = Math.max(0, Math.floor(Math.min(panel.left, pet.left) - 18)), y = Math.max(0, Math.floor(Math.min(panel.top, pet.top) - 18));
    return { x, y, width: Math.min(innerWidth - x, Math.ceil(Math.max(panel.right, pet.right) - x + 18)), height: Math.min(innerHeight - y, Math.ceil(Math.max(panel.bottom, pet.bottom) - y + 18)) };
  });
  await page.screenshot({ path: 'artifacts/session-inbox.png', clip });
  await page.keyboard.press('Escape');
  await receive({ type: 'notification-state', snapshot: state });
  const inline = {...request,state:'open',questions:[{id:'inline-q',header:'需要你决定',question:'下一步怎么办？',detail:'<img src=x onerror="throw 1"> 这只是说明',options:[{label:'再试一次',description:'在现有授权内重试，不增加权限。'},{label:'先停在这里',description:'暂停推进，不改文件。'}]}]};
  await receive({type:'snapshot',snapshot:frame([waitingA],[])});
  await receive({type:'notification-state',snapshot:{...state,interactions:[inline]}});
  await resetActions();await page.locator('#attention').click();
  await page.locator('.inline-question').evaluate(node => { if (!node.open) node.querySelector('summary').click(); });
  assert.match(await page.locator('.inline-question').innerText(),/在现有授权内重试/);
  assert.equal(await page.locator('.inline-question img').count(),0);
  assert.equal(await page.locator('.inline-question button[type=submit]').isDisabled(),true);
  await page.locator('.inline-question input[type=radio]').first().check();
  await page.locator('.inline-question form').evaluate(form=>{form.requestSubmit();form.requestSubmit();});
  const submitted=(await actions()).filter(a=>a.type==='question-answer');assert.equal(submitted.length,1);
  assert.deepEqual(submitted[0].answers,[{id:'inline-q',selected:['再试一次']}]);assert.equal(submitted[0].generation,8);
  await receive({...submitted[0],type:'question-answer-result',status:'accepted'});
  assert.equal(await page.locator('.inline-question button[type=submit]').isDisabled(),true);
  assert.match(await page.locator('.inline-question').innerText(),/已提交/);
  await receive({type:'notification-state',snapshot:state});assert.equal(await page.locator('.request-card').count(),0);
  const customInline={...inline,id:JSON.stringify([a.id,'question','custom-inline']),nativeId:'custom-inline'};
  await receive({type:'notification-state',snapshot:{...state,interactions:[customInline]}});
  await resetActions();await page.locator('.inline-question').evaluate(node => { if (!node.open) node.querySelector('summary').click(); });
  await page.locator('.inline-question input[type=radio]').first().check();
  await page.locator('.inline-question textarea').fill('先别改 utils.ts');
  assert.equal(await page.locator('.inline-question input:checked').count(),0);
  await page.locator('.inline-question button[type=submit]').click();
  const customSubmitted=(await actions()).find(a=>a.type==='question-answer');
  assert.deepEqual(customSubmitted.answers,[{id:'inline-q',selected:[],custom:'先别改 utils.ts'}]);
  await receive({...customSubmitted,type:'question-answer-result',status:'failed',code:'question/stale'});
  assert.match(await page.locator('.inline-question').innerText(),/已处理或已过期/);
  assert.equal(await page.locator('[data-request-id][data-action=open]').innerText(),'去 Harness 处理');
  await page.setViewportSize({width:320,height:640});
  await page.waitForFunction(()=>{const r=document.getElementById('requests').getBoundingClientRect();return r.left>=0&&r.right<=innerWidth&&r.top>=0&&r.bottom<=innerHeight;});
  assert.equal(await page.locator('#requests').evaluate(n=>n.scrollWidth<=n.clientWidth),true);
  await page.screenshot({path:'artifacts/inline-answers.png'});
  await receive({type:'configure',options:{inlineQuestions:false}});assert.equal(await page.locator('.inline-question').count(),0);
  await receive({type:'configure',options:{inlineQuestions:true}});
  for(const extra of [{multiSelect:true},{intent:{kind:'plan-review',approve:'再试一次'}}]){
    await receive({type:'notification-state',snapshot:{...state,interactions:[{...inline,questions:[{...inline.questions[0],...extra}]}]}});
    assert.equal(await page.locator('.inline-question').count(),0);
    assert.equal(await page.locator('[data-request-id][data-action=open]').isVisible(),true);
  }
  await receive({type:'notification-state',snapshot:state});await page.keyboard.press('Escape');
  await page.setViewportSize({width:1200,height:800});
  const opening='我把三项测试修好啦，详细证据在下面。', full=opening+'\n\n'+'这里是完整的检查说明。'.repeat(60);
  const bubbleFrame=id=>({...frame([],[]), sessions:[{...focus,unread:1}], results:[reply(id,focus,20,full)]});
  await receive({type:'configure',options:{preferOpeningParagraph:true}});
  await receive({type:'snapshot',snapshot:bubbleFrame('opening-enabled')});
  await page.locator('#bubble:not([hidden])').waitFor();
  assert.equal(await page.locator('#bubble-text').innerText(),opening);
  assert.equal(await page.locator('#bubble-expand').isVisible(),true);
  await page.locator('#bubble-expand').click();
  assert.equal(await page.locator('#reader-text').innerText(),full);
  await page.keyboard.press('Escape');
  await receive({type:'configure',options:{preferOpeningParagraph:false}});
  await receive({type:'snapshot',snapshot:bubbleFrame('opening-disabled')});
  await page.locator('#bubble:not([hidden])').waitFor();
  assert.ok((await page.locator('#bubble-text').innerText()).length>opening.length);
  assert.ok((await page.locator('#bubble-text').innerText()).endsWith('…'));
  // C09: quiet is a presentation preference, never a read/answer operation.
  await page.keyboard.press('Escape');
  for (const interfaceStyle of ['new', 'classic']) for (const locale of ['zh', 'en']) {
    const resultId = `quiet-${interfaceStyle}-${locale}`;
    const quietResult = reply(resultId, focus, Date.now(), 'Quiet full reply.\n\n完整正文。');
    const quietFrame = results => ({ ...frame([], results), sessions: [{ ...focus, replyId: results.at(-1)?.id, reply: results.at(-1)?.text ?? '' }] });
    const question = { ...request, id: resultId + '-request', nativeId: resultId + '-call', sessionId: focus.id, state: 'open', dueAt: null,
      questions: [{ id: resultId + '-q', question: 'Choose a plan', options: [{ label: 'A' }, { label: 'B' }] }] };
    const notice = { id: resultId + '-notice', sessionId: focus.id, turn: 1, seq: 2, time: Date.now(), category: 'question', stage: 'initial', title: 'Question', body: 'Choose a plan', requestIds: [question.id] };
    await receive({ type: 'init', baseline: true, options: { quietMode: true, companionship: 'off', locale, interfaceStyle, inlineQuestions: true }, snapshot: quietFrame([]) });
    await receive({ type: 'notification-state', snapshot: state });
    await resetActions();
    await receive({ type: 'snapshot', snapshot: quietFrame([quietResult]) });
    await receive({ type: 'notification-state', snapshot: { ...state, interactions: [question] } });
    await receive({ type: 'notice', notice });
    await receive({ type: 'notice', notice: { ...notice, id: notice.id + '-reminder', stage: 'reminder' } });
    assert.equal(await page.locator('#attention-count').innerText(), '2');
    for (const id of ['bubble', 'interaction', 'companion-invitation', 'companion-feedback', 'toast', 'requests', 'chat', 'reader']) assert.equal(await page.locator('#' + id).isVisible(), false, id + ' must stay closed');
    assert.deepEqual(await actions(), [], 'quiet arrivals cannot acknowledge or answer');
    assert.equal(await page.locator('#attention').evaluate(n => n.getAnimations().length), 0, 'reduced motion has no count pulse');
    await receive({ type: 'configure', options: { quietMode: false } });
    await page.evaluate(() => new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve))));
    assert.equal(await page.locator('#bubble').isVisible(), false, 'turning off cannot replay a quiet reply');
    assert.equal(await page.locator('#interaction').isVisible(), false, 'turning off cannot replay a notice');
    await receive({ type: 'configure', options: { quietMode: true } });
    await page.locator('#pet').dispatchEvent('contextmenu', { button: 2 });
    const toggle = page.locator('#toggle-quiet');
    assert.equal(await toggle.getAttribute('aria-checked'), 'true');
    assert.match(await toggle.innerText(), locale === 'zh' ? /安静模式/ : /Quiet mode/);
    await toggle.click();
    assert.deepEqual(await page.evaluate(() => window.inboxActions.filter(a => a.type === 'preference').at(-1)), { type: 'preference', field: 'quietMode', value: false });
    assert.equal(await toggle.getAttribute('aria-checked'), 'true', 'only the acknowledged configuration changes the switch');
    await page.keyboard.press('Escape');
    await page.locator('#attention').click();
    assert.equal(await page.locator('#request-list .request-card').count(), 1);
    assert.equal(await page.locator('#inbox-replies .inbox-reply').count(), 1);
    assert.equal(await page.locator('[data-action=snooze]').isDisabled(), false, 'quiet leaves remind me later usable');
    await page.locator('.inline-question').evaluate(node => { if (!node.open) node.querySelector('summary').click(); });
    await page.locator('.inline-question input[type=radio]').first().check();
    await page.locator('.inline-question button[type=submit]').click();
    const submitted = (await actions()).find(a => a.type === 'question-answer');
    assert.equal(submitted.interactionId, question.id);
    assert.deepEqual(submitted.answers, [{ id: resultId + '-q', selected: ['A'] }]);
    await receive({ ...submitted, type: 'question-answer-result', status: 'accepted' });
    // The redesigned "read" button is hidden in classic style; the reply body opens the reader in both.
    await page.locator('#inbox-replies .inbox-content').click();
    assert.equal(await page.locator('#reader-text').innerText(), quietResult.text);
    assert.ok((await actions()).some(a => a.type === 'read' && a.resultId === resultId));
    await page.keyboard.press('Escape');
    await receive({ type: 'notification-state', snapshot: state });
    await receive({ type: 'snapshot', snapshot: quietFrame([{ ...quietResult, read: true }]) });
    await page.locator('#pet').dblclick();
    await page.locator('#message').fill('preserved draft');
    const whileChat = reply(resultId + '-chat', focus, Date.now(), 'Reply in the open chat');
    await receive({ type: 'snapshot', snapshot: quietFrame([whileChat]) });
    assert.equal(await page.locator('#chat').isVisible(), true);
    assert.equal(await page.locator('#chat-reply').innerText(), whileChat.text);
    assert.equal(await page.locator('#message').inputValue(), 'preserved draft');
    assert.equal(await page.locator('#bubble').isVisible(), false);
    await page.locator('#message').fill('');
    await page.keyboard.press('Escape');
    // Local feedback is retained in the envelope, without a floating card.
    await receive({ type: 'configure', options: { companionship: 'interactive' } });
    await receive({ type: 'notification-state', snapshot: { ...state, interactions: [question] } });
    await page.locator('#pet').dispatchEvent('contextmenu', { button: 2 });
    await page.locator('#companion-play').click();
    assert.equal(await page.locator('#companion-feedback').isVisible(), false);
    await page.locator('#attention').click();
    assert.equal(await page.locator('[data-local-kind=feedback]').count(), 1);
    await page.locator('[data-local-kind=feedback] button').click();
    await page.keyboard.press('Escape');
    await receive({ type: 'notification-state', snapshot: state });
    await receive({ type: 'configure', options: { companionship: 'off', quietMode: false } });
    assert.equal(await page.locator('#bubble').isVisible(), false);
    const fresh = reply(resultId + '-fresh', focus, Date.now(), 'A fresh reply after quiet');
    await receive({ type: 'snapshot', snapshot: quietFrame([fresh]) });
    await page.locator('#bubble:not([hidden])').waitFor();
    assert.equal(await page.locator('#bubble-text').innerText(), fresh.text);
    await receive({ type: 'configure', options: { quietMode: true } });
    assert.equal(await page.locator('#bubble').isVisible(), false, 'enabling quiet withdraws the current bubble without reading it');
  }
  assert.deepEqual(errors, []);
  console.log('Inbox UI passed: one-click full reply, direct source actions, mixed pending items, stable chat focus and reading order, Unicode/text safety, bilingual copy and narrow layout.');
} finally { await browser?.close(); await new Promise(resolve => server.close(resolve)); await rm(directory, { recursive: true, force: true }); }
